function translateTextNodes(html, dictionary) {
  return html.replace(/>([^<>]+)</g, (whole, text) => {
    const trimmed = text.trim();
    const translated = dictionary[trimmed];
    if (!translated) return whole;
    return `>${text.replace(trimmed, translated)}<`;
  });
}

function localize(html, lang, page) {
  const dictionary = { ...common[lang], ...pageText[lang] };
  html = translateTextNodes(html, dictionary);
  html = html.replace('<html lang="en-CA">', `<html lang="${lang === 'zh' ? 'zh-CN' : 'es'}">`);
  const pagePath = page === 'index' ? '' : `${page}/`;
  const localizedUrl = `https://pacificspiritelectrical.ca/${lang}/${pagePath}`;
  html = html.replace(/<link rel="canonical" href="[^"]+">/, `<link rel="canonical" href="${localizedUrl}">`);
  html = html.replace(/<meta property="og:url" content="[^"]+">/, `<meta property="og:url" content="${localizedUrl}">`);
  html = html.replace(/<meta property="og:locale" content="[^"]+">/, `<meta property="og:locale" content="${lang === 'zh' ? 'zh_CN' : 'es_ES'}">`);
  if (projectMeta[page]) {
    const meta = projectMeta[page][lang];
    html = html.replace(/<title>[^<]+<\/title>/, `<title>${meta.title}</title>`);
    html = html.replace(/<meta name="description" content="[^"]+">/, `<meta name="description" content="${meta.description}">`);
    html = html.replace(/<meta property="og:title" content="[^"]+">/, `<meta property="og:title" content="${meta.title}">`);
    html = html.replace(/<meta property="og:description" content="[^"]+">/, `<meta property="og:description" content="${meta.description}">`);
  }
  html = html.replace(/href="\/(?!zh\/|es\/|images\/|favicon|#|contact\/\?)(services|about|service-areas|contact|privacy|projects)\//g, `href="/${lang}/$1/`);
  html = html.replace(/href="\/"/g, `href="/${lang}/"`);
  html = html.replace(/href="\/contact\/\?/g, `href="/${lang}/contact/?`);
  const englishPath = `/${pagePath}`;
  const zhPath = `/zh/${pagePath}`;
  const esPath = `/es/${pagePath}`;
  const currentName = lang === 'zh' ? '中文' : 'ES';
  const languageMenu = `<details class="language-menu"><summary aria-label="${lang === 'zh' ? '语言：中文' : 'Idioma: Español'}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg><span>${currentName}</span><span class="language-menu__chevron" aria-hidden="true">⌄</span></summary><nav aria-label="${lang === 'zh' ? '语言' : 'Idioma'}"><a href="${englishPath}" lang="en"><span>EN</span><small>English</small></a><a href="${zhPath}" lang="zh"${lang === 'zh' ? ' aria-current="true"' : ''}><span>中文</span><small>简体中文</small></a><a href="${esPath}" lang="es"${lang === 'es' ? ' aria-current="true"' : ''}><span>ES</span><small>Español</small></a></nav></details>`;
  html = html.replace(/<details class="language-menu">[\s\S]*?<\/details>/, languageMenu);
  const mobileLanguages = `<div class="language-switcher language-switcher--mobile"><a href="${englishPath}">EN</a><a href="${zhPath}"${lang === 'zh' ? ' aria-current="true"' : ''}>中文</a><a href="${esPath}"${lang === 'es' ? ' aria-current="true"' : ''}>ES</a></div>`;
  html = html.replace(/<div class="language-switcher language-switcher--mobile">[\s\S]*?<\/div>/, mobileLanguages);
  return html;
}

for (const page of pages) {
  const source = page === 'index' ? join('dist', 'index.html') : join('dist', page, 'index.html');
  const html = await readFile(source, 'utf8');
  for (const lang of ['zh', 'es']) {
    const target = page === 'index' ? join('dist', lang, 'index.html') : join('dist', lang, page, 'index.html');
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, localize(html, lang, page));
  }
}
